#!/usr/bin/env python3
"""As-of evidence snapshots: record and query the project state at a timestamp.

A snapshot is an append-only JSON manifest in .snapshots/<timestamp>.json.
The manifest records file path, size, and SHA-256 for every tracked file,
plus the wall-clock capture time and a content hash of the tree itself.
Snapshots are never mutated or deleted, so any earlier point in the
timeline remains inspectable ("as-of").
"""
import hashlib
import json
import os
import re
import sys
import time

SNAP_DIR = '.snapshots'
TS_FMT = '%Y%m%dT%H%M%S'
IGNORED_DIRS = {'.snapshots', '.git', '__pycache__', 'out', '.kuma'}
TS_RE = re.compile(r'^\d{8}T\d{6}Z?\.json$')


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()


def list_tracked_files(root='.'):
    files = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in IGNORED_DIRS]
        for name in sorted(filenames):
            p = os.path.join(dirpath, name)
            if os.path.islink(p):
                continue
            files.append(os.path.normpath(p))
    return sorted(files)


def capture(root='.', note=None):
    ts = time.strftime(TS_FMT, time.gmtime()) + 'Z'
    files = []
    for path in list_tracked_files(root):
        st = os.stat(path)
        files.append({
            'path': path,
            'size': st.st_size,
            'sha256': sha256_file(path),
        })
    manifest = {
        'schema': 'evidence-snapshot/1',
        'timestamp': ts,
        'note': note,
        'file_count': len(files),
        'files': files,
    }
    manifest['tree_sha256'] = hashlib.sha256(
        json.dumps(files, sort_keys=True).encode()).hexdigest()

    os.makedirs(SNAP_DIR, exist_ok=True)
    out = os.path.join(SNAP_DIR, ts + '.json')
    with open(out, 'w') as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write('\n')
    return manifest


def load_snapshots():
    if not os.path.isdir(SNAP_DIR):
        return []
    snaps = []
    for name in sorted(os.listdir(SNAP_DIR)):
        if not TS_RE.match(name):
            continue
        with open(os.path.join(SNAP_DIR, name)) as f:
            snaps.append(json.load(f))
    return snaps


def find_as_of(asof):
    """Latest snapshot whose timestamp <= asof (YYYYMMDD[THH[:MM[:SS]]])."""
    snaps = load_snapshots()
    if not snaps:
        return None
    for fmt in ('%Y%m%dT%H%M%S', '%Y%m%dT%H%M', '%Y%m%dT%H', '%Y%m%d'):
        try:
            cutoff = time.strftime(TS_FMT, time.strptime(asof, fmt))
        except ValueError:
            continue
        eligible = [s for s in snaps if s['timestamp'][:len(cutoff)] <= cutoff]
        return eligible[-1] if eligible else None
    raise ValueError(f'unparseable as-of timestamp: {asof!r}')


def verify(manifest):
    problems = []
    seen = {e['path']: e for e in manifest['files']}
    for entry in manifest['files']:
        p = entry['path']
        if not os.path.exists(p):
            problems.append(f'MISSING: {p}')
        elif os.path.getsize(p) != entry['size']:
            problems.append(f'SIZE MISMATCH: {p}')
        elif sha256_file(p) != entry['sha256']:
            problems.append(f'HASH MISMATCH: {p}')
    for path in list_tracked_files():
        if path not in seen:
            problems.append(f'UNTRACKED: {path}')
    if hashlib.sha256(json.dumps(
            manifest['files'], sort_keys=True).encode()).hexdigest() \
            != manifest.get('tree_sha256'):
        problems.append('MANIFEST TAMPERED: tree_sha256 mismatch')
    return problems


def cmd_as_of(asof, verify_flag=False):
    snap = find_as_of(asof)
    if snap is None:
        print('no snapshot at or before that time', file=sys.stderr)
        return 1
    print(f"as-of {asof} -> snapshot {snap['timestamp']}")
    print(f"  note: {snap.get('note')}")
    print(f"  files: {snap['file_count']}  tree: {snap['tree_sha256'][:16]}...")
    if verify_flag:
        problems = verify(snap)
        if problems:
            for p in problems:
                print(f'  {p}')
            return 1
        print('  verify: OK (all files match hashes)')
    return 0


def cmd_list():
    snaps = load_snapshots()
    if not snaps:
        print('no snapshots')
        return 0
    for s in snaps:
        print(f"{s['timestamp']}  files={s['file_count']}  "
              f"tree={s['tree_sha256'][:16]}  note={s.get('note')}")
    return 0


def main(argv):
    if not argv:
        print('usage: snapshot.py capture|list|as-of|verify [args]',
              file=sys.stderr)
        return 2
    cmd, rest = argv[0], argv[1:]
    if cmd == 'capture':
        note = None
        if rest:
            note = ' '.join(rest)
        m = capture(note=note)
        print(f"captured {m['timestamp']}  files={m['file_count']}  "
              f"tree={m['tree_sha256'][:16]}")
        return 0
    if cmd == 'list':
        return cmd_list()
    if cmd == 'as-of':
        if not rest:
            print('usage: snapshot.py as-of <timestamp> [--verify]',
                  file=sys.stderr)
            return 2
        return cmd_as_of(rest[0], verify_flag='--verify' in rest[1:])
    if cmd == 'verify':
        snaps = load_snapshots()
        if not snaps:
            print('no snapshots to verify', file=sys.stderr)
            return 1
        problems = verify(snaps[-1])
        if problems:
            for p in problems:
                print(p)
            return 1
        print(f"OK: {snaps[-1]['timestamp']} matches current tree "
              f"({snaps[-1]['file_count']} files)")
        return 0
    print(f'unknown command: {cmd}', file=sys.stderr)
    return 2


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
